// ✅ Dùng useRef lưu timerId và input focus
function Stopwatch() {
  const [seconds, setSeconds] = useState(0);
  const timerRef = useRef<number | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const start = () => {
    if (timerRef.current !== null) return;
    timerRef.current = window.setInterval(() => setSeconds((s) => s + 1), 1000);
    inputRef.current?.focus();
  };

  const stop = () => {
    if (timerRef.current !== null) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  return (
    <div>
      <input ref={inputRef} placeholder="Ghi chú..." />
      <p>Thời gian: {seconds}s</p>
      <button onClick={start}>Bắt đầu</button>
      <button onClick={stop}>Dừng</button>
    </div>
  );
}

// ✅ Tách đôi Context: CartStateContext & CartDispatchContext
import { createContext, useContext, useReducer } from 'react';

const CartStateCtx = createContext<CartState | null>(null);
const CartDispatchCtx = createContext<React.Dispatch<CartAction> | null>(null);

export function CartProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(cartReducer, initialCartState);
  return (
    <CartStateCtx.Provider value={state}>
      <CartDispatchCtx.Provider value={dispatch}>
        {children}
      </CartDispatchCtx.Provider>
    </CartStateCtx.Provider>
  );
}

// Custom hooks tiêu chuẩn:
export const useCartState = () => {
  const ctx = useContext(CartStateCtx);
  if (!ctx) throw new Error('useCartState must be used inside CartProvider');
  return ctx;
};

export const useCartDispatch = () => {
  const ctx = useContext(CartDispatchCtx);
  if (!ctx) throw new Error('useCartDispatch must be used inside CartProvider');
  return ctx;
};

